static bool rejected(json j){try{backup::validate(j);return false;}catch(...){return true;}}
int main(){json j={{"format","RetroWeatherSettings"},{"version",1},{"settings",{{"ZIP","01234"},{"SavedZips","01234,90210"},{"PageOrder","0,1,2,3,4,5,6"},{"ScenicAnimation","0"},{"ScenicTransparency","75"},{"MusicTrack","sample.wav"}}},{"locations",json::object()}};auto migrated=backup::validate(json::parse(j.dump()));assert(!migrated["settings"].contains("ScenicTransparency"));assert(migrated["version"]==2&&!migrated["settings"].contains("MusicTrack")&&!migrated["settings"].contains("ScenicAnimation"));auto bad=j;bad["version"]=3;assert(rejected(bad));bad=j;bad["settings"]["RestoreScreensaver"]="1";assert(rejected(bad));bad=j;bad["settings"]["UnknownPath"]="..\\outside.wav";assert(rejected(bad));bad=j;bad["settings"]["ScenicTransparency"]="42";assert(rejected(bad));bad=j;bad["settings"]["ZIP"]="12";assert(rejected(bad));bad=j;bad["settings"]["PageSeconds"]="0";assert(rejected(bad));bad=j;bad["settings"]["PageSeconds"]="999999999999999999999";assert(rejected(bad));bad=j;bad["settings"]["PageOrder"]="0,0,0";assert(rejected(bad));bad=j;bad["locations"]={{"12345",{{"zip","12345"},{"city","Test"},{"state","Test"},{"country","United States"},{"latitude",999},{"longitude",0}}}};assert(rejected(bad));
scenic::State scene;scene.rng=17;double last=-10;for(int i=0;i<24000;++i){scene.advance(.1);assert(std::isfinite(scene.time)&&scene.flashLength>=.45&&scene.flashLength<=.75);if(scene.flashStart!=last){assert(scene.nextFlash-scene.time>=12&&scene.nextFlash-scene.time<=23);last=scene.flashStart;}}std::cout<<"PASS: backup validation/migration; invalid schema, ranges, ZIP, order and coordinates; deterministic randomized lightning timing.\n";}
